export function parseCsv(text: string): Order[] {
    // Vendor exports start with a UTF-8 BOM; only strip it at the start so
    // plain UTF-8 input is unchanged.
    const withoutBom = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
    const lines = withoutBom.split(/\r?\n/).filter((line) => line.length > 0);

